#include "stdafx.h"#include <rsuNoNames.h>#include <TrendsSup.h>#include <QbBaseType_.h>#include <stdlib.h>#include <rsuErr.h>#include <Names.h>#include <UtilsQB.h>#ifdef _MANAGED#pragma managed(push, off)#endifKNoName g_qbIOs;BOOL APIENTRY DllMain( HMODULE hModule,                       DWORD  ul_reason_for_call,                       LPVOID lpReserved					 ){  switch (ul_reason_for_call)  {  case DLL_PROCESS_ATTACH:    g_qbIOs = KNoName::Create( "QB5xx_IOs", false );    break;  case DLL_THREAD_ATTACH:  case DLL_THREAD_DETACH:  case DLL_PROCESS_DETACH:    break;  }  return TRUE;}#ifdef _MANAGED#pragma managed(pop)#endifextern "C" Q_DECL_DLLEXPORT      bool EnumIOs(DWORD& ID, const DWORD ClassID, struct CBase** base, LPCSTR* pszName, int *pFcsNumber ){  return g_qbIOs.WhileBase( ID, ClassID, base, pszName, pFcsNumber );}struct SAddTrend {  char name[16];  SValueDef* def[id_QBAcyMax-id_QBAcyMin+1];};SAddTrend list[] ={  { "PV"  },  { "SP"  },  { "OP"  },};extern "C" __declspec(dllexport) int TrendInfoPoint(DWORD type, LPCSTR pObjName, CBase* pBase, int fcsNumber, int cInfs, STrendPointInfo *pInfs ){  DWORD N = pBase->ID_CLASS;  if( !IsQBAcy(N) )    return 0;  static bool bInited = false;  if( !bInited )  {    bInited = true;    for ( UINT n = 0; n < _countof(list); n++ )    {      for ( UINT m = id_QBAcyMin; m < id_QBAcyMax; m++ )      {        list[n].def[m-id_QBAcyMin] = NameToValueQB( m, list[n].name );      }    }  }  int c = 0;  for ( UINT n = 0; n < _countof(list); n++ )  {    if( list[n].def[N-id_QBAcyMin] == NULL )      continue;    if( c>= cInfs )      break;    STrendPointInfo &obj = pInfs[c];    obj.eValType = list[n].def[N-id_QBAcyMin]->eVal;    obj.dwID = GetID( pObjName, list[n].name, fcsNumber );    ASS( obj.dwID );    obj.pAddr = (BYTE*)(((BYTE*)pBase)+list[n].def[N-id_QBAcyMin]->dwShift);    obj.pszSufName = list[n].name;    c++;  }  return c;}